31
typedef struct {
/* identification */
char
saf_exit_impl_name[SAF_EXIT_IMPL_NAME_LEN + 1];
int
saf_exit_version;
/* group management */
int
(*saf_exit_add_group_entry)(char *aceeusri, char *groupname, char *owner,
char *supgroup);
