(*saf_exit_alter_user_entry)(char *aceeusri, char *userid, char *owner,
char *dfltgrp);
int
(*saf_exit_delete_user_entry)(char *aceeusri, char *userid);
/* connect & remove */
int
(*saf_exit_connect_entry)(char *aceeusri, char *userid, char *groupname,
